export function parseArgumentos(argv) {
  if (!Array.isArray(argv)) {
    throw new Error('argv precisa ser uma lista');
  }

  // --ajuda em qualquer posição: devolve o objeto de ajuda.
  for (const item of argv) {
    if (item === '--ajuda') {
      return { ajuda: true };
    }
  }

  // Cada par --chave valor vira chave: valor.
  // split('--') separa o prefixo: '--nome'.split('--') vira ['', 'nome'].
  const resultado = {};
  for (let i = 0; i < argv.length; i = i + 2) {
    const chave = argv[i];
    const valor = argv[i + 1];
    const nomeDaChave = chave && chave.split('--')[1];
    if (nomeDaChave !== undefined) {
      resultado[nomeDaChave] = valor;
    }
  }
  return resultado;
}

