import { parseArgumentos } from './argumentos.mjs';

export function saudacaoPara(argv) {
  const argumentos = parseArgumentos(argv);
  if (argumentos.ajuda === true) {
    return 'Uso: node saudacao.mjs --nome Ana --saudacao "Bom dia"';
  }
  const saudacao = argumentos.saudacao || 'Olá';
  const nome = argumentos.nome || 'visitante';
  return `${saudacao}, ${nome}!`;
}

