import { test } from 'node:test';
import assert from 'node:assert/strict';
import { parseArgumentos } from './lib/argumentos.mjs';
import { saudacaoPara } from './lib/saudacao.mjs';
import { criarPackageJson } from './lib/package.mjs';

test('parseArgumentos transforma --chave valor em objeto', () => {
  assert.deepEqual(
    parseArgumentos(['--nome', 'Ana', '--saudacao', 'Bom dia']),
    { nome: 'Ana', saudacao: 'Bom dia' }
  );
  assert.throws(() => parseArgumentos('--nome Ana'));
});

test('parseArgumentos com --ajuda devolve ajuda', () => {
  assert.deepEqual(parseArgumentos(['--ajuda']), { ajuda: true });
  assert.deepEqual(parseArgumentos(['--nome', 'Ana', '--ajuda']), { ajuda: true });
});

test('saudacaoPara usa parseArgumentos (do outro arquivo) para montar a frase', () => {
  assert.equal(saudacaoPara(['--nome', 'Ana', '--saudacao', 'Bom dia']), 'Bom dia, Ana!');
});

test('saudacaoPara usa padrões quando faltam argumentos', () => {
  assert.equal(saudacaoPara([]), 'Olá, visitante!');
  assert.equal(saudacaoPara(['--nome', 'Pedro']), 'Olá, Pedro!');
});

test('saudacaoPara com --ajuda devolve o texto de uso', () => {
  assert.equal(saudacaoPara(['--ajuda']), 'Uso: node saudacao.mjs --nome Ana --saudacao "Bom dia"');
});

test('criarPackageJson monta o package.json com scripts.start', () => {
  const pkg = criarPackageJson('saudacao', 'node saudacao.mjs');
  assert.equal(pkg.name, 'saudacao');
  assert.equal(pkg.version, '1.0.0');
  assert.equal(pkg.type, 'module');
  assert.equal(pkg.scripts.start, 'node saudacao.mjs');
});
